// Disposable database only: comment removals write permanent audit records.
export async function verifyD1News(db,factory){
 const news=factory(db,['boas-vindas','originais']),checks=[],names=['author','reader','private','mod','viewer','outsider','root'];
 const tokens=Object.fromEntries(names.map((n,i)=>[n,String(i+1).repeat(64)]));
 const run=(s,...p)=>db.prepare(s).bind(...p).run(),one=(s,...p)=>db.prepare(s).bind(...p).first();
 function check(ok,label){if(!ok)throw Error(label);checks.push(label);}
 async function fails(fn,label){let failed=false;try{await fn();}catch{failed=true;}check(failed,label);}
 const seed=[];for(const n of names){seed.push(db.prepare('INSERT INTO auth_accounts(id,username,password_hash,recovery_key_hash) VALUES(?,?,?,?)').bind('n10u_'+n,'n10_'+n,'hash','recovery_'+n));seed.push(db.prepare('INSERT INTO profiles(id,user_id,username) VALUES(?,?,?)').bind('n10p_'+n,'n10u_'+n,'n10_'+n));seed.push(db.prepare('INSERT INTO auth_sessions(id,user_id,token_hash,expires_at) VALUES(?,?,?,?)').bind('n10s_'+n,'n10u_'+n,tokens[n],new Date(Date.now()+3600000).toISOString()));}await db.batch(seed);
 await run("INSERT INTO platform_admins(user_id) VALUES('n10u_root')");
 await run("INSERT INTO departments(id,name,slug) VALUES('n10dept','Moderacao','moderacao'),('n10news','Jornal','jornal')");
 await run("INSERT INTO permissions(code,name,scope) VALUES('moderation.manage','Manage','department'),('moderation.view','View','department')");
 await run("INSERT INTO team_roles(id,department_id,name) VALUES('n10role','n10dept','Manager'),('n10view','n10dept','Viewer'),('n10foreign','n10news','Foreign')");
 await run("INSERT INTO team_role_permissions(role_id,permission_code) VALUES('n10role','moderation.manage'),('n10view','moderation.view'),('n10foreign','moderation.manage')");
 await run("INSERT INTO team_memberships(id,user_id,department_id,role_id) VALUES('n10m','n10u_mod','n10dept','n10role'),('n10v','n10u_viewer','n10dept','n10view'),('n10o','n10u_outsider','n10news','n10foreign')");
 await fails(()=>news.post(tokens.author,'n10bad','unknown','Hello'),'unknown article rejected');
 await fails(()=>news.post(tokens.author,'n10bad','boas-vindas','   '),'blank comment rejected');
 await fails(()=>news.post(tokens.author,'n10bad','boas-vindas','x'.repeat(3001)),'oversized comment rejected');
 await fails(()=>news.post('0'.repeat(64),'n10bad','boas-vindas','Hello'),'unknown session cannot post');
 await news.post(tokens.author,'n10parent','boas-vindas','Original comment');
 check((await news.comments(null,'boas-vindas'))[0]?.body==='Original comment','public comment visible anonymously');
 check((await news.comments(tokens.author,'boas-vindas'))[0]?.can_delete===1,'author can identify own removable comment');
 check((await news.comments(tokens.reader,'boas-vindas'))[0]?.can_delete===0,'reader cannot identify others comment as own');
 await fails(()=>news.post(tokens.reader,'n10cross','originais','Wrong article','n10parent'),'cross-article reply rejected');
 await news.post(tokens.reader,'n10reply','boas-vindas','A reply','n10parent');
 check((await one("SELECT user_id FROM user_notifications WHERE source_key='news-reply:n10reply'"))?.user_id==='n10u_author','reply notifies parent account');
 await news.post(tokens.author,'n10self','boas-vindas','A self reply','n10parent');
 check(!(await one("SELECT id FROM user_notifications WHERE source_key='news-reply:n10self'")),'self reply does not notify');
 await run("INSERT INTO profile_mutes(user_id,target_id) VALUES('n10p_author','n10p_reader')");
 await news.post(tokens.reader,'n10muted','boas-vindas','Muted reply','n10parent');
 check(!(await one("SELECT id FROM user_notifications WHERE source_key='news-reply:n10muted'")),'muted reply does not notify');
 await run("DELETE FROM profile_mutes WHERE user_id='n10p_author'");
 await run("UPDATE d1_runtime_flags SET value='1' WHERE key='suppress_notifications'");
 await news.post(tokens.reader,'n10historical','boas-vindas','Imported-style reply','n10parent');
 check(!(await one("SELECT id FROM user_notifications WHERE source_key='news-reply:n10historical'")),'import suppression prevents reply notification');
 await run("UPDATE d1_runtime_flags SET value='0' WHERE key='suppress_notifications'");
 await run("UPDATE profiles SET is_private=1 WHERE id='n10p_private'");
 await news.post(tokens.private,'n10private','boas-vindas','Private profile comment');
 check(!(await news.comments(null,'boas-vindas')).some(c=>c.id==='n10private'),'private profile comment hidden anonymously');
 check(!(await news.comments(tokens.reader,'boas-vindas')).some(c=>c.id==='n10private'),'private comment hidden from non-follower');
 await fails(()=>news.post(tokens.reader,'n10privreply','boas-vindas','Cannot read target','n10private'),'reply cannot bypass private profile');
 await run("INSERT INTO follows(follower_id,following_id) VALUES('n10p_reader','n10p_private')");
 check((await news.comments(tokens.reader,'boas-vindas')).some(c=>c.id==='n10private'),'accepted follower sees private comment');
 await news.post(tokens.reader,'n10privreply','boas-vindas','Follower reply','n10private');
 await run("INSERT INTO chat_blocks(blocker_id,blocked_id) VALUES('n10p_private','n10p_reader')");
 check(!(await news.comments(tokens.reader,'boas-vindas')).some(c=>c.id==='n10private'),'block overrides accepted follow');
 await fails(()=>news.post(tokens.reader,'n10blocked','boas-vindas','Blocked reply','n10private'),'blocked reply rejected');
 await fails(()=>news.remove(tokens.reader,'n10bad_audit','boas-vindas','n10parent'),'non-owner cannot remove comment');
 await fails(()=>news.remove(tokens.viewer,'n10bad_audit','boas-vindas','n10parent'),'read-only moderator cannot remove comment');
 await fails(()=>news.remove(tokens.outsider,'n10bad_audit','boas-vindas','n10parent'),'other department cannot moderate news');
 await fails(()=>news.remove(tokens.author,'n10bad_audit','originais','n10parent'),'removal is bound to article');
 await news.remove(tokens.mod,'n10audit','boas-vindas','n10parent');
 const tombstone=(await news.comments(null,'boas-vindas')).find(c=>c.id==='n10parent');
 check(tombstone?.deleted===1&&tombstone.body===null&&tombstone.author_id===null&&tombstone.username===null,'removed comment masks body and author');
 check((await news.comments(null,'boas-vindas')).some(c=>c.id==='n10reply'&&c.parent_id==='n10parent'),'removal preserves reply threading');
 check((await one("SELECT actor_user_id FROM admin_audit_log WHERE id='n10audit'"))?.actor_user_id==='n10u_mod','moderation audit records actual account');
 await fails(()=>news.post(tokens.reader,'n10deletedreply','boas-vindas','Reply to deleted','n10parent'),'deleted comment cannot receive new reply');
 await fails(()=>news.remove(tokens.root,'n10again','boas-vindas','n10parent'),'second removal does not create another audit');
 await fails(()=>news.remove(tokens.root,'n10audit','boas-vindas','n10reply'),'audit collision aborts removal');
 check((await one("SELECT deleted_at FROM news_comments WHERE id='n10reply'"))?.deleted_at===null,'failed audit preserves live comment');
 await news.remove(tokens.reader,'n10own','boas-vindas','n10reply');
 check((await one("SELECT deleted_by FROM news_comments WHERE id='n10reply'"))?.deleted_by==='n10p_reader','owner removal records profile separately from audit account');
 await run("UPDATE news_comments SET created_at='2026-01-01T00:00:00.000Z' WHERE id IN('n10self','n10muted')");
 const page=await news.comments(null,'boas-vindas',1,{createdAt:'2026-01-01T00:00:01Z',id:'z'});
 check(page[0]?.id==='n10self','cursor sorts equal dates by descending ID');
 const next=await news.comments(null,'boas-vindas',1,{createdAt:page[0].created_at,id:page[0].id});
 check(next[0]?.id==='n10muted','cursor avoids duplicates across timestamp ties');
 await fails(()=>news.comments(null,'boas-vindas',0),'invalid page size rejected');
 await run("UPDATE profiles SET moderation_hidden_at='2026-01-01T00:00:00Z' WHERE id='n10p_private'");
 check(!(await news.comments(tokens.private,'boas-vindas')).some(c=>c.id==='n10private'),'moderation-hidden profile loses public comment visibility');
 await run("UPDATE team_roles SET status='archived' WHERE id='n10role'");
 await fails(()=>news.remove(tokens.mod,'n10archived','boas-vindas','n10self'),'archived moderator cannot remove');
 await run("UPDATE auth_sessions SET expires_at='2000-01-01T00:00:00Z' WHERE id='n10s_root'");
 await fails(()=>news.remove(tokens.root,'n10expired','boas-vindas','n10self'),'expired administrator cannot remove');
 const rates=[];for(let i=0;i<20;i++)rates.push(db.prepare("INSERT INTO news_comments(id,article_slug,author_id,body) VALUES(?,'originais','n10p_outsider','rate sample')").bind('n10rate'+i));await db.batch(rates);
 await fails(()=>news.post(tokens.outsider,'n10limit','boas-vindas','Over limit'),'rate limit applies across articles');
 await run("UPDATE news_comments SET deleted_at='2026-01-01T00:00:00Z' WHERE author_id='n10p_outsider'");
 await fails(()=>news.post(tokens.outsider,'n10limit','boas-vindas','Over limit'),'soft deletion cannot reset posting rate');
 await run("DELETE FROM news_comments WHERE id='n10parent'");
 check((await one("SELECT parent_id FROM news_comments WHERE id='n10self'"))?.parent_id===null,'physical parent deletion clears only child parent reference');
 check((await one("SELECT article_slug FROM news_comments WHERE id='n10self'"))?.article_slug==='boas-vindas','physical parent deletion preserves child article');
 await run("UPDATE auth_accounts SET account_status='suspended' WHERE id='n10u_author'");
 await fails(()=>news.post(tokens.author,'n10suspended','boas-vindas','Suspended post'),'suspended account cannot post');
 return{passed:checks.length,checks};
}
